    'loader.quote': '"যদি তুমি সূর্যের মতো জ্বলতে চাও, তবে প্রথমে সূর্যের মতো পুড়ো।" তিনি আরও বলেছেন, "শ্রেষ্ঠত্ব একটি অবিরাম প্রক্রিয়া, দুর্ঘটনা নয়।"',
    'loader.author': '— এ.পি.জে. আবদুল কালাম',
