    'hero.here': 'শুরু হয়।',
    'hero.description': 'নেতা, উদ্ভাবক এবং পরিবর্তনকারীদের পরবর্তী প্রজন্মকে ক্ষমতায়ন। একসাথে, আমরা মনকে জাগ্রত করি এবং আমাদের জাতির জন্য একটি উজ্জ্বল আগামীকাল গড়ে তুলি।',
