    'hero.here': 'सुरू होते.',
    'hero.description': 'नेते, नवप्रवर्तक आणि परिवर्तनकर्त्यांच्या पुढील पिढीला सक्षम करणे. एकत्रितपणे, आम्ही मनाला प्रज्वलित करतो आणि आमच्या राष्ट्रासाठी एक उज्ज्वल उद्या घडवतो.',
