    'president.message1': 'پرنو سچندرن ایک نوجوان قوم ساز، سفارتی مفکر، محقق، عوامی اسپیکر اور یوتھ لیڈر ہیں جن کا کام راشٹر دیو بھو — قوم سب سے اعلیٰ فرض ہے — کے لازوال آئیڈیل میں لنگر انداز ہے۔',
    'president.message2': 'اگنائٹ یوتھ کمیونٹی (IYC) کے صدر کی حیثیت سے، پرنو ایک سادہ یقین پر مبنی ایک نوجوان تحریک کو شکل دے رہے ہیں: ایک بااختیار، باخبر اور ذمہ دار نوجوان ایک ترقی یافتہ قوم کی بنیاد ہے۔ ان کا وژن علم کی تقسیم، رہنمائی، ہم مرتبہ سے ہم مرتبہ تعلیم، قیادت کی ترقی، اور نوجوانوں کے لیے ایک دوسرے سے سیکھنے اور بڑھنے کے بامعنی مواقع پیدا کرنے پر مرکوز ہے۔',
    'president.message3': 'نیا وانی کے ذریعے اپنے اختراعی کام کے لیے قومی اعزاز یافتہ، پرنو نوجوان رہنماؤں کی ایک نئی نسل کی نمائندگی کرتے ہیں جو جدت کو سماجی مقصد کے ساتھ، سفارت کاری کو یقین کے ساتھ، اور قیادت کو خدمت کے ساتھ جوڑنا چاہتے ہیں۔',
    'president.message4': '"سفارتی مستند ٹریل بلیزر" کے طور پر ان کی منفرد شناخت قیادت کے بارے میں ان کے نقطہ نظر کی عکاسی کرتی ہے—سوچ میں اسٹریٹجک، مقصد میں مستند، مصروفیت میں سفارتی، اور عمل میں پیش پیش۔',
    'president.message5': 'پرنو کے لیے، نوجوانوں کی قیادت پیروکار بنانے کا نام نہیں ہے؛ یہ رہنما بنانے کا نام ہے۔ IYC کے ذریعے، وہ مشترکہ علم، ہم مرتبہ رہنمائی، فکری تجسس، شہری ذمہ داری اور اجتماعی ترقی کی ثقافت بنانے کی کوشش کرتے ہیں۔',
    'president.message6': 'ہر اقدام بالآخر ایک بڑی قومی تمنا کی طرف مرکوز ہوتا ہے: وکست بھارت۔ راشٹر دیو بھو کے جذبے سے رہنمائی اور یووا شکتی سے تقویت یافتہ، پرنو نوجوان ہندوستانیوں کو ہندوستان کی تبدیلی کے محض گواہ نہیں، بلکہ اس کے مستقبل کے فعال معمار بننے کی ترغیب دینا چاہتے ہیں۔',
    'president.signoff': 'نوجوانوں کو روشن کریں۔ علم بانٹیں۔ رہنما بنائیں۔ قوم کی خدمت کریں۔',
    'president.viksit': 'وکست بھارت کی طرف۔',
    'founder.name': 'سچندرن کوئمبٹور شنکررامن',
    'founder.title': 'بانی اور وژنری | شریشٹھا فاؤنڈیشن',
    'founder.message1': 'سچندرن کوئمبٹور شنکررامن شریشٹھا فاؤنڈیشن کے بانی اور وژنری ہیں، جو علم، جدت، صلاحیت کی ترقی اور کمیونٹی کو بااختیار بنانے کے ذریعے پائیدار قدر پیدا کرنے کے لیے پرعزم ایک مقصد پر مبنی مائیکرو، چھوٹے اور درمیانے درجے کا ادارہ (MSME) ہے۔',
    'founder.message2': 'شریشٹھا فاؤنڈیشن کے لیے ان کا وژن ایک مخصوص ادارہ جاتی پلیٹ فارم بنانا ہے جو پیشہ ورانہ مشاورت، تعلیم و تربیت، کاروباریت، پائیدار زراعت اور ماحولیاتی اقدامات، اور نوجوانوں کی ترقی کو اکٹھا کرتا ہے—معاشی مواقع اور سماجی اثرات کے درمیان بامعنی تقاطع پیدا کرتا ہے۔',
    'founder.message3': 'علم کی تبدیلی کی طاقت پر پختہ یقین کے ساتھ، سچندرن اس نقطہ نظر کی حمایت کرتے ہیں جس میں سیکھنا صلاحیت کی طرف، صلاحیت کاروبار کی طرف، اور کاروبار پائیدار ترقی میں اپنا حصہ ڈالتا ہے۔ ان کی کوششیں افراد، پیشہ ور افراد، کاروباری افراد، کسانوں اور نوجوانوں کے لیے متعلقہ علم حاصل کرنے، عملی صلاحیتیں پیدا کرنے اور اپنی صلاحیت کو پیداواری نتائج میں تبدیل کرنے کے قابل رسائی راستے بنانے پر مرکوز ہیں۔',
    'founder.message4': 'ایک MSME کے طور پر، شریشٹھا فاؤنڈیشن ان کے اس یقین کی عکاسی کرتی ہے کہ چھوٹے، چست ادارے جدت اور نچلی سطح کی تبدیلی کے لیے طاقتور اتپریرک بن سکتے ہیں۔ فاؤنڈیشن کاروبار اور مقصد کے سنگم پر کام کرنا چاہتی ہے، ایسے اقدامات تیار کرنا جو پیشہ ورانہ طور پر منظم، عملی طور پر متعلقہ اور سماجی طور پر بامعنی ہوں۔',
    'founder.message5': 'سچندرن کی قیادت کا فلسفہ دیانت، مسلسل سیکھنے، جدت، پائیداری اور ذمہ دارانہ ترقی میں لنگر انداز ہے۔ وہ شریشٹھا فاؤنڈیشن کو محض پروگرام اور خدمات فراہم کرنے والی تنظیم کے طور پر نہیں، بلکہ ایک ابھرتے ہوئے ماحولیاتی نظام کے طور پر دیکھتے ہیں جو لوگوں کو سیکھنے، تخلیق کرنے، قیادت کرنے اور حصہ ڈالنے کے قابل بناتا ہے۔',
    'founder.message6': 'شریشٹھا فاؤنڈیشن کے ذریعے، ان کی بڑی تمنا خود انحصاری، کاروباریت اور ذمہ دار شہریت کی ثقافت کو فروغ دینا ہے، جبکہ پائیدار روزگار، علم پر مبنی ترقی اور مضبوط کمیونٹیز میں اپنا حصہ ڈالنا ہے۔',
    'founder.signoff': 'صلاحیت کی تعمیر۔ مواقع کی تخلیق۔ پائیدار ترقی کو فروغ۔',
    'founder.vision': 'سچندرن کی قیادت میں، شریشٹھا فاؤنڈیشن ایک معتبر MSME ادارے کے طور پر ترقی کرنے کی تمنا رکھتی ہے جو خیالات کو اقدامات میں، علم کو صلاحیت میں اور صلاحیت کو پائیدار اثر میں تبدیل کرتا ہے۔',
    'footer.brand': 'اگنائٹ یوتھ کمیونٹی',
    'footer.description': 'قائدین، جدت پسندوں اور تبدیلی لانے والوں کی اگلی نسل کو بااختیار بنانا۔',
    'footer.contact': 'ہم سے رابطہ کریں',
    'footer.follow': 'ہمیں فالو کریں',
    'footer.links': 'فوری لنکس',
    'footer.home': 'ہوم',
    'footer.about': 'ہمارے بارے میں',
    'footer.wings': 'ونگز',
    'footer.gallery': 'گیلری',
    'footer.activities': 'ہماری سرگرمیاں',
    'footer.join': 'IYC میں شامل ہوں',
    'footer.rights': 'جملہ حقوق محفوظ ہیں۔',
    'footer.tagline': 'نوجوانوں کو روشن کریں۔ علم بانٹیں۔ رہنما بنائیں۔ قوم کی خدمت کریں۔',
