    'footer.tagline': 'ಯುವಕರನ್ನು ಪ್ರಜ್ವಲಿಸಿ. ಜ್ಞಾನವನ್ನು ಹಂಚಿಕೊಳ್ಳಿ. ನಾಯಕರನ್ನು ರಚಿಸಿ. ರಾಷ್ಟ್ರದ ಸೇವೆ ಮಾಡಿ.',
