    'hero.welcome': 'ଇଗ୍ନାଇଟ୍ ଯୁଥ୍ କମ୍ୟୁନିଟିକୁ ସ୍ୱାଗତ',
    'hero.subtitle': '(ଶ୍ରେଷ୍ଠା ଫାଉଣ୍ଡେସନର ଏକ ୟୁନିଟ୍)',
    'hero.bharat': 'ଭାରତର',
