    'hero.here': 'ଆରମ୍ଭ ହୁଏ।',
    'hero.description': 'ନେତା, ନବସୃଷ୍ଟିକାରୀ ଏବଂ ପରିବର୍ତ୍ତନକାରୀଙ୍କ ପରବର୍ତ୍ତୀ ପିଢ଼ିକୁ ସଶକ୍ତ କରିବା। ଏକତ୍ର, ଆମେ ମନକୁ ପ୍ରଜ୍ୱଳିତ କରୁ ଏବଂ ଆମ ରାଷ୍ଟ୍ର ପାଇଁ ଏକ ଉଜ୍ଜ୍ୱଳ ଭବିଷ୍ୟତ ନିର୍ମାଣ କରୁ।',
