    'loader.quote': '"যদি আপুনি সূৰ্য্যৰ দৰে জিলিকিব বিচাৰে, তেন্তে প্ৰথমে সূৰ্য্যৰ দৰে জ্বলিব।" তেওঁ লগতে কৈছিল, "শ্ৰেষ্ঠতা হৈছে এক নিৰন্তৰ প্ৰক্ৰিয়া, দুৰ্ঘটনা নহয়।"',
