    'hero.here': 'আৰম্ভ হয়।',
    'hero.description': 'নেতা, উদ্ভাৱক আৰু পৰিৱৰ্তনকাৰীসকলৰ পৰৱৰ্তী প্ৰজন্মক সবলীকৰণ। একেলগে, আমি মনক প্ৰজ্বলিত কৰো আৰু আমাৰ ৰাষ্ট্ৰৰ বাবে এটা উজ্জ্বল কালি নিৰ্মাণ কৰো।',
