    'footer.join': 'IYC ᱨᱮ ᱥᱮᱞᱮᱫ ᱢᱮ',
    'footer.rights': 'ᱡᱚᱛᱚ ᱟᱫᱷᱤᱠᱟᱨ ᱨᱟᱠᱷᱟᱭ ᱢᱮ᱾',
    'footer.tagline': 'ᱭᱩᱣᱟ ᱠᱚ ᱡᱚᱞᱟᱣ ᱢᱮ᱾ ᱜᱮᱭᱟᱱ ᱦᱟᱹᱴᱤᱧ ᱢᱮ᱾ ᱱᱮᱛᱟ ᱵᱮᱱᱟᱣ ᱢᱮ᱾ ᱫᱤᱥᱚᱢ ᱨᱮᱱᱟᱜ ᱥᱮᱣᱟ ᱢᱮ᱾',
