    'hero.here': 'شُروع چھُ گَژھان۔',
    'hero.description': 'رہنُما، نٔو کٲری کَرن والؠن تہِ تبدیلی خٲطرٕ کَم کَرن والؠن نؠوِس نَسٕلَس تَخت کرُن۔ اَکھٹھ، اَسہِ ذہن تَیز کَران تہِ پَزِہٕ قومَس خٲطرٕ اَکھ رۄہَن راتھ بَنان۔',
