    'loader.quote': '"यदि तपाईं सूर्यजस्तै चम्कन चाहनुहुन्छ भने, पहिले सूर्यजस्तै जल्नुहोस्।" उनले यो पनि भने, "उत्कृष्टता एक निरन्तर प्रक्रिया हो, दुर्घटना होइन।"',
