    'hero.here': 'सुरु हुन्छ।',
    'hero.description': 'नेता, नवप्रवर्तक र परिवर्तनकारीहरूको अर्को पुस्तालाई सशक्त बनाउने। सँगै, हामी दिमागलाई प्रज्वलित गर्छौं र हाम्रो राष्ट्रको लागि उज्ज्वल भोलिको निर्माण गर्छौं।',
