    'president.leadership': 'IYC اڳواڻي',
    'president.designation': 'صدر، اگنائٽ يوتھ ڪميونٽي',
    'president.name': 'پرڻو سچندرن',
    'president.title': 'صدر، اگنائٽ يوتھ ڪميونٽي (IYC)',
    'president.tags': 'سفارتي اختياري ٽري بلېزر | قومي انعام يافته | يوتھ ليڊر',
    'president.message1': 'پرڻو سچندرن ھڪ نوجوان قوم-ساز، سفارتي مفڪر، محقق، عوامي اسپيڪر ۽ يوتھ ليڊر آھن، جن جو ڪم راشٽر ڊيوو ڀَو — قوم سڀ کان وڏو فرض آھي — جي لازوال آدرش ۾ لنگر انداز آھي۔',
    'president.message2': 'اگنائٽ يوتھ ڪميونٽي (IYC) جي صدر جي حيثيت ۾، پرڻو ھڪ سادي يقين تي ٻڌل يوتھ تحريڪ کي شڪل ڏئي رھيا آھن: ھڪ بااختيار، ڄاڻو ۽ ذميوار نوجوان ھڪ ترقي يافته قوم جو بنياد آھي۔ سندن ويزن علم جي ونڊ، رھنمائي، ساٿي-کان-ساٿي تعليم، اڳواڻي ترقي، ۽ نوجوانن لاءِ ھڪ ٻئي کان سکڻ ۽ وڌڻ لاءِ معنيٰ خيز موقعا پيدا ڪرڻ تي مرکوز آھي۔',
    'president.message3': 'نيائہ واني ذريعي سندن جديد ڪم لاءِ قومي انعام يافته، پرڻو نوجوان اڳواڻن جي ھڪ نئين نسل جي نمائندگي ڪن ٿا جيڪي جدت کي سماجي مقصد سان، سفارت کي يقين سان، ۽ اڳواڻي کي خدمت سان گڏ ڪرڻ چاھين ٿا۔',
    'president.message4': '"سفارتي اختياري ٽري بلېزر" جي حيثيت ۾ سندن منفرد سڃاڻپ اڳواڻي جي سندن طريقي کي ظاھر ڪري ٿي—سوچ ۾ حڪمت عملي، مقصد ۾ اختياري، مصروفيت ۾ سفارتي، ۽ عمل ۾ پائونيئر۔',
    'president.message5': 'پرڻو لاءِ، يوتھ اڳواڻي پوئلڳ ٺاھڻ بابت ناھي؛ اھو اڳواڻ ٺاھڻ بابت آھي۔ IYC ذريعي، ھو حصيداري علم، ساٿي رھنمائي، فڪري تجسس، شهري ذميواري ۽ اجتماعي ترقي جي ثقافت تعمير ڪرڻ جي ڪوشش ڪن ٿا۔',
    'president.message6': 'ھر قدم آخرڪار ھڪ وڏي قومي تمنا جي طرف مرکوز ٿئي ٿو: وڪست ڀارت۔ راشٽر ڊيوو ڀَو جي روح سان رھنمائي ۽ يووا شڪتي سان طاقت ورتي، پرڻو نوجوان ھندستانين کي ھندستان جي تبديلي جي رڳو شاھد نه، پر ان جي مستقبل جا فعال معمار بڻجڻ لاءِ متاثر ڪرڻ چاھين ٿا۔',
    'president.signoff': 'نوجوانن کي روشن ڪريو۔ علم ونڊيو۔ اڳواڻ ٺاھيو۔ قوم جي خدمت ڪريو۔',
    'president.viksit': 'وڪست ڀارت ڏانهن۔',
    'founder.name': 'سچندرن ڪوئمبٽور شنڪررامن',
    'founder.title': 'باني ۽ ويزنري | شريشٺا فائونڊيشن',
    'founder.message1': 'سچندرن ڪوئمبٽور شنڪررامن شريشٺا فائونڊيشن جا باني ۽ ويزنري آھن، جيڪو علم، جدت، صلاحيت ترقي ۽ ڪميونٽي کي بااختيار بڻائڻ ذريعي پائيدار قدر پيدا ڪرڻ لاءِ پرعزم ھڪ مقصد-چاليت مائڪرو، سمول اينڊ مڊيم اينٽرپرائز (MSME) آھي۔',
    'founder.message2': 'شريشٺا فائونڊيشن لاءِ سندن ويزن ھڪ منفرد اداري پليٽ فارم تعمير ڪرڻ آھي جيڪو پيشه ورانه صلاح، تعليم ۽ تربيت، وابستگي، پائيدار زراعت ۽ ماحولياتي قدم، ۽ يوتھ ترقي کي گڏ آڻي ٿو—معاشي موقعي ۽ سماجي اثر جي وچ ۾ معنيٰ خيز چونڪون پيدا ڪري ٿو۔',
    'founder.message3': 'علم جي تبديلي واري طاقت تي مضبوط يقين سان، سچندرن ان طريقي جي حمايت ڪن ٿا جنھن ۾ سکيا صلاحيت ڏانهن، صلاحيت وابستگي ڏانهن، ۽ وابستگي پائيدار ترقي ۾ حصو ڏئي ٿي۔ سندن ڪوششون فردن، پيشه ورن، وابستگي ڪندڙن، هارين ۽ نوجوانن لاءِ لاڳاپيل علم حاصل ڪرڻ، عملي صلاحيتون ترقي ڪرڻ ۽ پنھنجي صلاحيت کي پيداواري نتيجن ۾ تبديل ڪرڻ لاءِ رسائي لائق رستا ٺاھڻ تي مرکوز آھن۔',
    'founder.message4': 'MSME جي حيثيت ۾، شريشٺا فائونڊيشن سندن ان يقين کي ظاھر ڪري ٿي ته ننڍا، چست ادارا جدت ۽ بنيادي تبديلي لاءِ طاقتور اتپريڪ بڻجي سگھن ٿا۔ فائونڊيشن وابستگي ۽ مقصد جي چونڪ تي ڪم ڪرڻ چاھي ٿي، اھڙا قدم ترقي ڪري ٿي جيڪي پيشه ورانه طور تي جوڙيل، عملي طور تي لاڳاپيل ۽ سماجي طور تي معنيٰ خيز آھن۔',
    'founder.message5': 'سچندرن جي اڳواڻي فلسفو ايمانداري، مسلسل سکيا، جدت، پائيداري ۽ ذميوار ترقي ۾ لنگر انداز آھي۔ ھو شريشٺا فائونڊيشن کي رڳو پروگرام ۽ خدمتون فراهم ڪندڙ تنظيم جي طور تي نه، پر ھڪ ترقي پذير ماحولياتي نظام جي طور تي ڏسن ٿا جيڪو ماڻھن کي سکڻ، تخليق ڪرڻ، اڳواڻي ڪرڻ ۽ حصو ڏيڻ جي قابل بڻائي ٿو۔',
    'founder.message6': 'شريشٺا فائونڊيشن ذريعي، سندن وڏي تمنا خود انحصاري، وابستگي ۽ ذميوار شهريت جي ثقافت کي فروغ ڏيڻ آھي، گڏوگڏ پائيدار روزي، علم-چاليت ترقي ۽ مضبوط ڪميونٽيز ۾ حصو ڏيڻ آھي۔',
    'founder.signoff': 'صلاحيت تعمير۔ موقعو تخليق۔ پائيدار ترقي کي اڳتي وڌائڻ۔',
    'founder.vision': 'سچندرن جي اڳواڻي ھيٺ، شريشٺا فائونڊيشن ھڪ قابل اعتماد MSME ادارو طور وڌڻ جي تمنا رکي ٿو جيڪو خيالن کي قدمن ۾، علم کي صلاحيت ۾ ۽ صلاحيت کي پائيدار اثر ۾ تبديل ڪري ٿو۔',
    'footer.brand': 'اگنائٽ يوتھ ڪميونٽي',
