    'loader.quote': '"ꯅꯪ ꯅꯨꯃꯤꯠ ꯃꯤꯠ ꯌꯦꯡꯅꯕ ꯄꯥꯝꯃꯤꯗꯤ, ꯍꯥꯛꯇ ꯅꯨꯃꯤꯠ ꯃꯤꯠ ꯁꯥꯗꯅꯥ ꯂꯥꯛꯄ ꯌꯥꯢ।" ꯃꯍꯥꯛꯅ ꯍꯥꯏꯈꯤ, "ꯃꯔꯨꯡ ꯑꯁꯤ ꯃꯤꯠꯀꯤ ꯄꯨꯟꯁꯤ ꯑꯃꯅꯤ, ꯑꯉꯥꯡ ꯅꯠꯇꯦ।"',
