    'hero.description': 'ꯂꯨꯆꯤꯡꯕ, ꯅꯨꯡꯁꯤꯠ ꯁꯦꯝꯕ ꯑꯃꯁꯨꯡ ꯍꯣꯡꯍꯟꯕꯒꯤ ꯃꯇꯨꯡ ꯏꯟꯅ ꯂꯥꯛꯀꯤ ꯃꯤꯁꯦꯜ ꯑꯗꯨ ꯃꯤꯅꯥ ꯄꯨꯛꯅꯤꯡ ꯊꯧꯒꯠꯄ ꯌꯥꯍꯤ। ꯑꯩꯈꯣꯏ ꯅꯨꯡꯉꯣꯡꯗ, ꯑꯩꯈꯣꯏ ꯃꯤꯠ ꯊꯧꯒꯠꯄ ꯌꯥꯍꯤ ꯑꯃꯁꯨꯡ ꯑꯩꯈꯣꯏꯒꯤ ꯂꯩꯄꯥꯛ ꯑꯁꯤꯒꯤ ꯑꯉꯥꯡ ꯅꯨꯃꯤꯠ ꯑꯃ ꯁꯦꯝꯒꯠꯄ ꯌꯥꯍꯤ।',
    'stats.students': 'ꯃꯤꯅꯥ ꯄꯨꯛꯅꯤꯡ ꯊꯧꯒꯠꯄ ꯃꯤꯁꯦꯜ',
