    'president.message1': 'प्रणवः सुचिन्द्रनः नवयुवा राष्ट्र-निर्माता, राजनैतिकः चिन्तकः, शोधकः, सार्वजनिकः वक्ता, युवा नेता च, यस्य कार्यं राष्ट्र देवो भव — राष्ट्रं सर्वोच्चं कर्तव्यम् — इति कालातीतम् आदर्शम् आधारितम् अस्ति।',
    'president.message2': 'इग्नाइट यूथ कम्युनिटी (IYC) अध्यक्षत्वेन, प्रणवः एकं सरलं विश्वासम् आधारितं युवा आन्दोलनं रूपयति: एकः सशक्तः, ज्ञानी, उत्तरदायी च युवा विकसितस्य राष्ट्रस्य आधारः। तस्य दृष्टिः ज्ञान-विभाजनम्, मार्गदर्शनम्, सहपाठी-तः-सहपाठी शिक्षणम्, नेतृत्व-विकासः, युवेभ्यः च अन्योन्यं शिक्षितुं वृद्धिं च प्राप्तुं सार्थकानि अवसराणि निर्मातुं केन्द्रिता।',
