    'president.message5': 'प्रणवस्य कृते, युवा नेतृत्वम् अनुयायिनः निर्मातुं न, अपि तु नेतॄन् निर्मातुम्। IYC मार्गेण, सः सहभागीकृतं ज्ञानम्, सहपाठी मार्गदर्शनम्, बौद्धिकम् कौतूहलम्, नागरिकम् उत्तरदायित्वम्, सामूहिकं विकासं च संस्कृतिं निर्मातुं प्रयतते।',
    'president.message6': 'प्रत्येकं उपक्रमं अन्ततः एकं बृहत् राष्ट्रियम् आकांक्षां प्रति केन्द्रितम् भवति: विक्सित भारतम्। राष्ट्र देवो भव आत्मना निर्देशितः, युवा शक्त्या च चालितः, प्रणवः नवयुवान् भारतीयान् भारतस्य परिवर्तनस्य केवलं साक्षिणः न, अपि तु तस्य भविष्यस्य सक्रियाः वास्तुकाराः भवितुं प्रेरयितुम् इच्छति।',
